package todo.domain

class TodoSuite extends munit.FunSuite:

  test("create rejects a blank title") {
    assertEquals(Todo.create(Todo.Id(1), ""), Left(Todo.Error.BlankTitle))
  }

  test("create rejects a whitespace-only title") {
    assertEquals(Todo.create(Todo.Id(1), "   \t  "), Left(Todo.Error.BlankTitle))
  }

  test("create succeeds for a non-blank title, defaulting done to false") {
    val result = Todo.create(Todo.Id(1), "buy milk")
    assertEquals(result.map(_.title), Right("buy milk"))
    assertEquals(result.map(_.done), Right(false))
  }

  test("create trims surrounding whitespace from an otherwise valid title") {
    assertEquals(Todo.create(Todo.Id(1), "  buy milk  ").map(_.title), Right("buy milk"))
  }

  test("create never throws, even for pathological input") {
    Todo.create(Todo.Id(1), "�")
  }

  test("nextId is one for an empty list") {
    assertEquals(Todo.nextId(Nil), Todo.Id(1))
  }

  test("nextId is one greater than the largest existing id") {
    val existing = List(
      Todo.create(Todo.Id(5), "a").toOption.get,
      Todo.create(Todo.Id(2), "b").toOption.get
    )
    assertEquals(Todo.nextId(existing), Todo.Id(6))
  }

