package todo.store

import munit.CatsEffectSuite
import todo.domain.Todo

import java.nio.file.{Files, Path}

class StoreSuite extends CatsEffectSuite:

  private def tempPath(): Path =
    Files.createTempDirectory("todo-store-suite").resolve("todos.yaml")

  test("reading a store path that does not exist yields an empty list") {
    Store.read(tempPath()).assertEquals(Nil)
  }

  test("writing todos and reading them back round-trips to an equal list") {
    val path = tempPath()
    val todos = List(
      Todo.create(Todo.Id(1), "buy milk").toOption.get,
      Todo.create(Todo.Id(2), "walk the dog", done = true).toOption.get
    )
    for
      _      <- Store.write(path, todos)
      result <- Store.read(path)
    yield assertEquals(result, todos)
  }

  test("reading a malformed store file fails fast with a descriptive error") {
    val path = tempPath()
    Files.writeString(path, "not: [valid, todo, schema")
    Store.read(path).attempt.map {
      case Left(err) => assert(err.getMessage.nonEmpty, "expected a descriptive error message")
      case Right(todos) => fail(s"expected reading a malformed store to fail, got $todos")
    }
  }

