package todo.store

import cats.effect.IO
import cats.syntax.all.*
import org.virtuslab.yaml.*
import todo.domain.Todo

import java.nio.file.{Files, Path}

/** Raised when the store file exists but its content is not a valid todo list. */
final case class StoreError(message: String) extends Exception(message)

/** Reads and writes the one YAML file that backs the todo list. The path is always an explicit
  * parameter — there is no global, hardcoded store location — so callers (and tests) point it at
  * whatever file they need.
  */
object Store:

  /** The on-disk shape of a `Todo`: plain data, decoupled from the domain's smart constructor so
    * the YAML codec never has to know about `Todo.Id` or the blank-title invariant.
    */
  private final case class Row(id: Long, title: String, done: Boolean) derives YamlCodec

  /** A store file that does not exist yet has no todos — that is not an error. */
  def read(path: Path): IO[List[Todo]] =
    IO.blocking(Files.exists(path)).flatMap {
      case false => IO.pure(Nil)
      case true  => IO.blocking(Files.readString(path)).flatMap(parse)
    }

  def write(path: Path, todos: List[Todo]): IO[Unit] =
    val rows = todos.map(t => Row(t.id.value, t.title, t.done))
    IO.blocking(Files.writeString(path, rows.asYaml)).void

  private def parse(content: String): IO[List[Todo]] =
    // An empty file carries no todos, same as a missing one; a non-empty file must parse.
    if content.isBlank then IO.pure(Nil)
    else
      content.as[List[Row]] match
        case Left(err)   => IO.raiseError(StoreError(s"malformed store: ${err.msg}"))
        case Right(rows) => rows.traverse(toTodo)

  private def toTodo(row: Row): IO[Todo] =
    IO.fromEither(
      Todo
        .create(Todo.Id(row.id), row.title, row.done)
        .leftMap(_ => StoreError(s"malformed store: blank title for id ${row.id}"))
    )

