package todo.cli

import cats.effect.{ExitCode, IO}
import todo.domain.Todo
import todo.store.Store

import java.nio.file.Path

/** What a command produced: the process exit code and the message for the user. Keeping this a
  * plain value (instead of printing directly) is what lets tests assert on command behaviour
  * without capturing stdout.
  */
final case class Outcome(exitCode: ExitCode, message: String)

object Cli:

  def add(path: Path, title: String): IO[Outcome] =
    Store.read(path).flatMap { existing =>
      Todo.create(Todo.nextId(existing), title) match
        case Left(Todo.Error.BlankTitle) =>
          IO.pure(Outcome(ExitCode.Error, "error: title must not be blank"))
        case Right(todo) =>
          Store
            .write(path, existing :+ todo)
            .as(Outcome(ExitCode.Success, s"added todo ${todo.id.value}: ${todo.title}"))
    }

  def list(path: Path): IO[Outcome] =
    Store.read(path).map {
      case Nil   => Outcome(ExitCode.Success, "no todos")
      case todos => Outcome(ExitCode.Success, Render.plain(todos))
    }

/** Minimal, unformatted rendering for M3 — M4 replaces this with an aligned table. */
private[cli] object Render:

  def plain(todos: List[Todo]): String =
    todos.map(line).mkString("\n")

  private def line(t: Todo): String =
    val mark = if t.done then "x" else " "
    s"[$mark] ${t.id.value}: ${t.title}"

