  private def runCommand(outcome: IO[Outcome]): IO[ExitCode] =
    outcome.flatMap(o => IO.println(o.message).as(o.exitCode))

  private def usage(args: List[String]): String =
    s"""unrecognized command: ${args.mkString(" ")}
